<script setup>
import { reactive } from 'vue'
import { Link, router, useForm } from '@inertiajs/vue3'
const props=defineProps({course:Object,lesson:Object,role:String})
const form=useForm({title:'',description:'',status:'DRAFT',available_at:'',due_at:'',allow_late_submission:false,allow_resubmission:false,max_attempts:null})
const editing=reactive({})
const submit=()=>form.post(`/${props.role}/courses/${props.course.id}/lessons/${props.lesson.id}/assignments`,{onSuccess:()=>form.reset()})
const edit=a=>editing[a.id]={title:a.title,description:a.description||'',status:a.status,available_at:a.available_at?.slice(0,16)||'',due_at:a.due_at?.slice(0,16)||'',allow_late_submission:a.allow_late_submission,allow_resubmission:a.allow_resubmission,max_attempts:a.max_attempts}
const save=a=>router.put(`/assignments/${a.id}`,editing[a.id],{onSuccess:()=>delete editing[a.id]})
</script>
<template><section class="rounded-2xl border bg-white p-6"><h2 class="mb-4 font-bold">تکالیف درس</h2>
<article v-for="a in lesson.assignments" :key="a.id" class="mb-3 rounded-xl bg-slate-50 p-4">
<div v-if="editing[a.id]" class="grid gap-3 md:grid-cols-2"><input v-model="editing[a.id].title" aria-label="عنوان تکلیف"><select v-model="editing[a.id].status" aria-label="وضعیت"><option value="DRAFT">پیش‌نویس</option><option value="PUBLISHED">منتشرشده</option><option value="INACTIVE">غیرفعال</option></select><textarea v-model="editing[a.id].description" class="md:col-span-2 w-full rounded-xl border p-3"></textarea><input v-model="editing[a.id].available_at" type="datetime-local"><input v-model="editing[a.id].due_at" type="datetime-local"><label><input v-model="editing[a.id].allow_late_submission" type="checkbox"> ارسال دیرهنگام</label><label><input v-model="editing[a.id].allow_resubmission" type="checkbox"> ارسال مجدد</label><input v-model="editing[a.id].max_attempts" type="number" min="1" placeholder="حداکثر تلاش"><div class="flex gap-2"><button class="rounded-lg bg-teal-700 px-3 py-2 text-white" @click="save(a)">ذخیره</button><button class="rounded-lg border px-3 py-2" @click="delete editing[a.id]">انصراف</button></div></div>
<div v-else class="flex flex-wrap items-center justify-between gap-3"><div><strong>{{a.title}}</strong><p class="text-xs">{{a.status}} <span v-if="a.deleted_at">— بایگانی‌شده</span></p></div><div class="flex gap-3"><button v-if="!a.deleted_at" class="text-teal-700" @click="edit(a)">ویرایش</button><Link v-if="!a.deleted_at" :href="`/assignments/${a.id}`" method="delete" as="button" class="text-red-700">بایگانی</Link><Link v-else-if="role==='admin'" :href="`/admin/assignments/${a.id}/restore`" method="post" as="button">بازیابی</Link></div></div>
</article>
<form class="mt-5 grid gap-3 md:grid-cols-2" @submit.prevent="submit"><div><label>عنوان</label><input v-model="form.title"><p class="text-red-600">{{form.errors.title}}</p></div><div><label>وضعیت</label><select v-model="form.status"><option value="DRAFT">پیش‌نویس</option><option value="PUBLISHED">منتشرشده</option><option value="INACTIVE">غیرفعال</option></select></div><div class="md:col-span-2"><label>توضیحات</label><textarea v-model="form.description" class="w-full rounded-xl border p-3"></textarea></div><div><label>زمان دسترسی</label><input v-model="form.available_at" type="datetime-local"></div><div><label>مهلت ارسال</label><input v-model="form.due_at" type="datetime-local"><p class="text-red-600">{{form.errors.due_at}}</p></div><label><input v-model="form.allow_late_submission" type="checkbox"> اجازه ارسال پس از مهلت</label><label><input v-model="form.allow_resubmission" type="checkbox"> اجازه ارسال مجدد</label><div><label>حداکثر تلاش (خالی یعنی نامحدود)</label><input v-model="form.max_attempts" type="number" min="1"></div><button :disabled="form.processing" class="rounded-xl bg-teal-700 px-4 py-2 text-white">ایجاد تکلیف</button></form>
</section></template>
